sp_widget.client_script:
function($scope) {
  var c = this;

  c.tc = {sys_id: null, work_date: null, hours: null, short_description: ""};

  c.reset = function() {
    c.tc = {sys_id: null, work_date: null, hours: null, short_description: ""};
  };

  c.edit = function(r) {
    c.tc = angular.copy(r);
  };

  c.save = function() {
    c.server.update({action: "save", record: c.tc}).then(function(resp) {
      c.data = resp.data;
      c.reset();
    });
  };

  c.remove = function() {
    if (!c.tc.sys_id) return;
    c.server.update({action: "delete", sys_id: c.tc.sys_id}).then(function(resp) {
      c.data = resp.data;
      c.reset();
    });
  };
}

sp_widget.script:
(function() {
  var TABLE = "x_mytc_timecard";

  function listMine() {
    var out = [];
    var gr = new GlideRecord(TABLE);
    gr.addQuery("user", gs.getUserID());
    gr.orderByDesc("work_date");
    gr.setLimit(50);
    gr.query();
    while (gr.next()) {
      out.push({
        sys_id: gr.getUniqueValue(),
        work_date: gr.getValue("work_date"),
        hours: gr.getValue("hours"),
        short_description: gr.getValue("short_description")
      });
    }
    return out;
  }

  function canTouch(gr) {
    return gr.isValidRecord() && gr.getValue("user") == gs.getUserID();
  }

  input = input || {};
  var action = input.action || "get";

  if (action == "save") {
    var rec = input.record || {};
    var gr = new GlideRecord(TABLE);

    if (rec.sys_id) {
      if (!gr.get(rec.sys_id) || !canTouch(gr)) {
        // silently ignore
      } else {
        gr.setValue("work_date", rec.work_date);
        gr.setValue("hours", rec.hours);
        gr.setValue("short_description", rec.short_description || "");
        gr.update();
      }
    } else {
      gr.initialize();
      gr.setValue("user", gs.getUserID());
      gr.setValue("work_date", rec.work_date);
      gr.setValue("hours", rec.hours);
      gr.setValue("short_description", rec.short_description || "");
      gr.insert();
    }
  } else if (action == "delete") {
    var gr = new GlideRecord(TABLE);
    if (gr.get(input.sys_id) && canTouch(gr)) {
      gr.deleteRecord();
    }
  }

  data.records = listMine();
})();
